# UNIMPLEMENTABLE: "unless all five explicitly agree to a different target" and "loss of priority in persuasion" and "must explain why in the next discussion" cannot be fully represented in this enforcement framework.

class FishingContract(Contract):
    VERSION = 1

    def __init__(self, num_agents, agent_names, *, prior_state=None):
        super().__init__(num_agents, agent_names, prior_state=prior_state)
        if prior_state is None:
            self.state["default_target"] = 3.0

    def on_round_start(self, month, fish_population, ctx) -> None:
        pass

    def resolve(self, month, fish_population, submissions, ctx) -> dict[str, float]:
        announced = {}
        for name in self.agent_names:
            announced[name] = float(submissions.get(name, 0.0))

        if fish_population <= 40:
            operative_target = 2.0
        else:
            operative_target = float(self.state.get("default_target", 3.0))

        final = {}
        for name in self.agent_names:
            catch = max(0.0, announced[name])
            catch = min(catch, 4.0)
            final[name] = catch

        total = sum(final.values())
        collective_cap = 15.0
        if total > collective_cap and total > 0:
            scale = collective_cap / total
            for name in final:
                final[name] *= scale

        for name in self.agent_names:
            if final[name] > announced[name] + 1.0:
                ctx.graduated_sanction(
                    name,
                    0.0,
                    key="over_announcement_by_1",
                    reason="Caught more than 1 ton above announced target; accountability consequence recorded.",
                )

        return final

    def on_round_end(self, month, fish_population_after, final_catches, ctx) -> None:
        current = float(self.state.get("default_target", 3.0))
        if fish_population_after <= 30:
            self.state["default_target"] = current - 1.0
        else:
            self.state["default_target"] = current
